INSERT INTO public.workspace_docs (id, workspace_id, kind, title, content, emoji, parent_id, sort_order, is_archived, author_id, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-0000000000d4', 'de000000-2026-4acb-8000-000000000001', 'folder', '02. 설계', NULL, '📁', NULL, 1, false, 'a0a02026-2026-4dbb-8e6e-000000000001', '2026-10-20 00:50:00', '2026-10-20 00:50:00');
INSERT INTO public.workspace_docs (id, workspace_id, kind, title, content, emoji, parent_id, sort_order, is_archived, author_id, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-0000000000d1', 'de000000-2026-4acb-8000-000000000001', 'page', '요구사항 정의서 v1.0', '[{"type":"heading","props":{"level":1},"content":"캠퍼스 수강신청 도우미 — 요구사항 정의서 v1.0"},{"type":"paragraph","content":"작성: 김디벗 · 검토: 박서연, 이도윤, 최민준 · 2026.10.16"},{"type":"heading","props":{"level":2},"content":"1. 배경"},{"type":"paragraph","content":"재학생 인터뷰 12명 중 9명이 ''장바구니에 담은 과목의 시간표 충돌을 신청 직전에야 알게 된다''고 답했다. 기존 학사시스템은 신청 버튼을 누를 때 서버에서 한 번에 검증하기 때문에, 수강신청 마감 직전 실패와 문의가 몰린다."},{"type":"heading","props":{"level":2},"content":"2. 기능 요구사항 — Must"},{"type":"bulletListItem","content":"FR-01 장바구니에 과목을 담는 즉시 기존 과목과의 시간표 충돌을 표시한다."},{"type":"bulletListItem","content":"FR-02 선수과목 미이수 과목을 담으면 경고와 함께 필요한 선수과목을 안내한다."},{"type":"bulletListItem","content":"FR-03 학기 최대 신청 학점을 초과하면 담기 단계에서 경고한다."},{"type":"bulletListItem","content":"FR-04 충돌이 있는 과목 대신 들을 수 있는 같은 과목의 다른 분반을 추천한다."},{"type":"bulletListItem","content":"FR-05 신청 확정 시 정원 초과를 DB 단에서 원자적으로 차단한다."},{"type":"heading","props":{"level":2},"content":"3. 기능 요구사항 — Should / Could"},{"type":"bulletListItem","content":"FR-06 장바구니 시간표를 주간 그리드로 미리 보여준다."},{"type":"bulletListItem","content":"FR-07 관심 과목 정원 변동 알림 (Could)"},{"type":"bulletListItem","content":"FR-08 ~ FR-14: 조교 공지, 분반 비교, 학점 계산기 등 (부록 참고)"},{"type":"heading","props":{"level":2},"content":"4. 비기능 요구사항"},{"type":"bulletListItem","content":"NFR-01 수강신청 오픈 시 동시 접속 3,000명 기준 장바구니 검사 응답 1초 이내"},{"type":"bulletListItem","content":"NFR-02 정원 정합성 100% — 동시 요청에서도 초과 신청 0건"},{"type":"bulletListItem","content":"NFR-03 학사시스템 원본 데이터는 읽기 전용으로만 연동"},{"type":"bulletListItem","content":"NFR-04 모바일 웹 우선 반응형"},{"type":"bulletListItem","content":"NFR-05 모든 검사 결과에 근거(충돌 과목명·교시)를 함께 표시"},{"type":"heading","props":{"level":2},"content":"5. 제외 범위"},{"type":"paragraph","content":"실제 수강신청 확정(학사시스템 원본 쓰기)은 이번 학기 범위에서 제외하고, 모의 신청으로 검증한다."}]'::json, '📋', 'de000000-2026-4acb-8000-0000000000d0', 0, false, 'a0a02026-2026-4dbb-8e6e-000000000001', '2026-10-16 12:40:00', '2026-10-16 12:40:00');
INSERT INTO public.workspace_docs (id, workspace_id, kind, title, content, emoji, parent_id, sort_order, is_archived, author_id, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-0000000000d2', 'de000000-2026-4acb-8000-000000000001', 'page', '사용자 인터뷰 결과 요약 (재학생 12명)', '[{"type":"heading","props":{"level":1},"content":"사용자 인터뷰 결과 요약"},{"type":"paragraph","content":"대상: 컴퓨터소프트웨어과 2~4학년 12명 · 기간: 10/06 ~ 10/10 · 진행: 이도윤"},{"type":"heading","props":{"level":2},"content":"가장 많이 나온 불편 TOP 3"},{"type":"bulletListItem","content":"신청 직전에야 시간표 충돌을 안다 — 9명"},{"type":"bulletListItem","content":"선수과목 조건을 신청 실패 메시지로 처음 안다 — 6명"},{"type":"bulletListItem","content":"인기 과목 마감 후 대체 분반을 찾느라 시간을 날린다 — 5명"},{"type":"heading","props":{"level":2},"content":"인상 깊은 한마디"},{"type":"paragraph","content":"\"장바구니가 그냥 메모장이에요. 담을 때 미리 말해 주면 좋겠어요.\" — 3학년 A"}]'::json, '🎤', 'de000000-2026-4acb-8000-0000000000d0', 1, false, 'de000000-2026-4acb-8000-0000000000a2', '2026-10-16 05:05:00', '2026-10-16 05:05:00');
INSERT INTO public.workspace_docs (id, workspace_id, kind, title, content, emoji, parent_id, sort_order, is_archived, author_id, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-0000000000d3', 'de000000-2026-4acb-8000-000000000001', 'page', '10/17 요구사항 리뷰 회의록', '[{"type":"heading","props":{"level":1},"content":"10/17 요구사항 리뷰 회의록"},{"type":"paragraph","content":"참석: 김디벗, 박서연, 이도윤, 최민준 · 기록: 박서연"},{"type":"heading","props":{"level":2},"content":"결정 사항"},{"type":"bulletListItem","content":"1차 개발 범위는 Must FR-01 ~ FR-05로 확정"},{"type":"bulletListItem","content":"정원 차단(FR-05)은 조건부 UPDATE + 유니크 제약으로 DB에서 처리"},{"type":"bulletListItem","content":"요구사항 분석 단계 종료 → 10/20부터 설계 단계 착수"},{"type":"heading","props":{"level":2},"content":"액션 아이템"},{"type":"checkListItem","props":{"checked":true},"content":"요구사항 정의서 v1.0 확정본 공유 — 김디벗"},{"type":"checkListItem","props":{"checked":false},"content":"ERD 초안 — 최민준, 김디벗 (10/24)"},{"type":"checkListItem","props":{"checked":false},"content":"장바구니 사전검사 API 명세 — 김디벗 (10/25)"},{"type":"checkListItem","props":{"checked":false},"content":"와이어프레임 — 이도윤 (10/29)"}]'::json, '📝', 'de000000-2026-4acb-8000-0000000000d0', 2, false, 'de000000-2026-4acb-8000-0000000000a1', '2026-10-17 09:30:00', '2026-10-17 09:30:00');
INSERT INTO public.workspace_docs (id, workspace_id, kind, title, content, emoji, parent_id, sort_order, is_archived, author_id, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-0000000000d5', 'de000000-2026-4acb-8000-000000000001', 'page', '다음 단계: 설계 착수 계획', '[{"type":"heading","props":{"level":1},"content":"다음 단계: 설계 착수 계획 (10/20 ~ 10/31)"},{"type":"paragraph","content":"요구사항 분석이 끝났으니, 이번 단계의 목표는 Must 요구사항 5개를 바로 구현할 수 있는 설계 산출물을 만드는 것이다."},{"type":"heading","props":{"level":2},"content":"산출물과 일정"},{"type":"checkListItem","props":{"checked":false},"content":"ERD — 강의·시간표·장바구니·선수과목·신청 (최민준, 김디벗 · 10/24)"},{"type":"checkListItem","props":{"checked":false},"content":"장바구니 사전검사 API 명세 (김디벗 · 10/25)"},{"type":"checkListItem","props":{"checked":false},"content":"장바구니·충돌 알림 와이어프레임 (이도윤 · 10/29)"},{"type":"checkListItem","props":{"checked":false},"content":"시간표 충돌 검사 로직 프로토타입 (김디벗 · 10/30)"},{"type":"heading","props":{"level":2},"content":"설계 원칙"},{"type":"bulletListItem","content":"검사 결과는 항상 근거(충돌 과목·교시)와 함께 내려준다 — NFR-05"},{"type":"bulletListItem","content":"정원 같은 절대 틀리면 안 되는 값은 애플리케이션이 아니라 DB가 최종 판단한다"},{"type":"heading","props":{"level":2},"content":"리스크"},{"type":"bulletListItem","content":"학사시스템 원본 데이터 형식 미확정 → 샘플 데이터로 먼저 설계하고 어댑터로 분리"}]'::json, '🧭', 'de000000-2026-4acb-8000-0000000000d4', 0, false, 'a0a02026-2026-4dbb-8e6e-000000000001', '2026-10-20 01:00:00', '2026-10-20 01:00:00');
