INSERT INTO public.workspace_channels (id, workspace_id, name, description, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-0000000000f1', 'de000000-2026-4acb-8000-000000000001', 'general', '팀 공지와 기본 대화를 나누는 채널', 'PUBLIC', '2026-10-05 23:00:00', '2026-10-05 23:00:00');
INSERT INTO public.workspace_channels (id, workspace_id, name, description, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-0000000000f2', 'de000000-2026-4acb-8000-000000000001', 'dev-log', '작업 진행 상황과 개발 메모를 공유하는 채널', 'PUBLIC', '2026-10-05 23:00:00', '2026-10-05 23:00:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001001', 'de000000-2026-4acb-8000-0000000000f1', 'de000000-2026-4acb-8000-0000000000a2', '인터뷰 12명 정리 끝났습니다! 가장 많이 나온 불편은 ''신청 직전에야 시간표 충돌을 안다''(9/12명)였어요. 요약 올려뒀어요 [!de000000-2026-4acb-8000-0000000000d2:사용자 인터뷰 결과 요약 (재학생 12명)]', 'TEXT', '2026-10-16 05:05:00', '2026-10-16 05:05:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001002', 'de000000-2026-4acb-8000-0000000000f1', 'de000000-2026-4acb-8000-0000000000a3', '학사시스템 흐름 분석해 보니 장바구니 단계엔 검사가 전혀 없고, 신청 버튼 누를 때 한 번에 검증하더라고요. 그래서 마감 직전에 실패 문의가 몰리는 구조예요.', 'TEXT', '2026-10-16 05:12:00', '2026-10-16 05:12:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001003', 'de000000-2026-4acb-8000-0000000000f1', 'a0a02026-2026-4dbb-8e6e-000000000001', '요구사항 정의서 v1.0 올렸습니다 [!de000000-2026-4acb-8000-0000000000d1:요구사항 정의서 v1.0] 기능 14개 / 비기능 5개로 정리했고, 내일 리뷰 때 우선순위 같이 정해요.', 'TEXT', '2026-10-16 12:40:00', '2026-10-16 12:40:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001004', 'de000000-2026-4acb-8000-0000000000f1', 'de000000-2026-4acb-8000-0000000000a1', '오늘 리뷰 회의록 정리했어요 [!de000000-2026-4acb-8000-0000000000d3:10/17 요구사항 리뷰 회의록] Must는 FR-01~05로 확정!', 'TEXT', '2026-10-17 09:30:00', '2026-10-17 09:30:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001005', 'de000000-2026-4acb-8000-0000000000f1', 'a0a02026-2026-4dbb-8e6e-000000000001', '요구사항 분석 단계는 여기서 마감할게요 🎉 이번 주부터 설계 단계 들어갑니다. 계획은 [!de000000-2026-4acb-8000-0000000000d5:다음 단계: 설계 착수 계획] 에 정리했어요.', 'TEXT', '2026-10-20 01:02:00', '2026-10-20 01:02:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001006', 'de000000-2026-4acb-8000-0000000000f1', 'a0a02026-2026-4dbb-8e6e-000000000001', '[@de000000-2026-4acb-8000-0000000000a3:최민준] 님이랑 ERD 먼저 잡고 [#de000000-2026-4acb-8000-0000000000e6:ERD 설계 — 강의·시간표·장바구니·선수과목], 저는 사전검사 API 명세 초안 맡을게요 [#de000000-2026-4acb-8000-0000000000e7:장바구니 사전검사 API 명세 초안]', 'TEXT', '2026-10-20 01:05:00', '2026-10-20 01:05:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001007', 'de000000-2026-4acb-8000-0000000000f1', 'de000000-2026-4acb-8000-0000000000a3', '넵! 수강신청 테이블은 정원 동시성 때문에 신청 인원 컬럼 따로 둘게요. 오늘 저녁에 초안 공유드릴게요', 'TEXT', '2026-10-20 01:11:00', '2026-10-20 01:11:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001008', 'de000000-2026-4acb-8000-0000000000f1', 'de000000-2026-4acb-8000-0000000000a2', 'ERD 나오면 바로 장바구니 화면 와이어프레임 시작할게요 ✏️', 'TEXT', '2026-10-20 01:20:00', '2026-10-20 01:20:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001009', 'de000000-2026-4acb-8000-0000000000f1', 'de000000-2026-4acb-8000-0000000000a1', '저는 그동안 Next.js 세팅이랑 디자인 토큰 먼저 준비해 둘게요', 'TEXT', '2026-10-20 01:24:00', '2026-10-20 01:24:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001010', 'de000000-2026-4acb-8000-0000000000f1', 'a0a02026-2026-4dbb-8e6e-000000000001', '[@de000000-2026-4acb-8000-0000000000a1:박서연] [@de000000-2026-4acb-8000-0000000000a2:이도윤] 오늘 15시에 설계 킥오프 15분만 할게요. 다음 할 일은 [#de000000-2026-4acb-8000-0000000000e8:시간표 충돌 검사 로직 프로토타입] 이에요.', 'TEXT', '2026-10-21 00:15:00', '2026-10-21 00:15:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000001011', 'de000000-2026-4acb-8000-0000000000f1', 'de000000-2026-4acb-8000-0000000000a1', '좋아요 👍', 'TEXT', '2026-10-21 00:18:00', '2026-10-21 00:18:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000002001', 'de000000-2026-4acb-8000-0000000000f2', 'de000000-2026-4acb-8000-0000000000a3', '[분석] 학사시스템 수강신청 화면 6개 캡처 & 흐름도 정리 완료 — 검증 시점은 신청 버튼(서버) 1회뿐', 'TEXT', '2026-10-15 14:10:00', '2026-10-15 14:10:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000002002', 'de000000-2026-4acb-8000-0000000000f2', 'a0a02026-2026-4dbb-8e6e-000000000001', '[요구사항] FR-01 담기 즉시 시간표 충돌 표시 / FR-02 선수과목 미이수 경고 / FR-03 학점 상한 초과 경고 / FR-04 대체 분반 추천 / FR-05 정원 원자적 차단 — v1.0 반영', 'TEXT', '2026-10-16 13:00:00', '2026-10-16 13:00:00');
INSERT INTO public.workspace_messages (id, channel_id, sender_id, content, type, created_at, updated_at) VALUES ('de000000-2026-4acb-8000-000000002003', 'de000000-2026-4acb-8000-0000000000f2', 'de000000-2026-4acb-8000-0000000000a3', '[설계] ERD 초안 v0.1 — lecture, lecture_time, cart_item, prerequisite, enrollment(신청 인원 컬럼 분리). 리뷰 부탁드려요', 'TEXT', '2026-10-20 10:40:00', '2026-10-20 10:40:00');
